insert into public.events (title, slug, excerpt, description, event_date, start_time, end_time, venue, address, map_link, cover_image_url, status, featured) values
  ('Community Health Day: Makoko', 'community-health-day-makoko', 'Free blood pressure, blood sugar and malaria screening for families in Makoko, with nurses on site all day.', '<p>Our quarterly health day returns to Makoko. Nurses and doctors from our partner clinics will offer free screening for blood pressure, blood sugar and malaria, plus advice for expectant mothers.</p><p>No appointment is needed. Bring any previous test results if you have them. Children are welcome and there will be a play area.</p><h2>What to expect</h2><ul><li>Free screening and same-day results</li><li>Maternal health talk at 11:00</li><li>Referrals to partner clinics where needed</li></ul>', '2026-10-19', '09:00', '15:00', 'Makoko Community Hall', 'Makoko, Yaba, Lagos', 'https://maps.google.com/?q=Makoko,+Lagos', 'https://images.unsplash.com/photo-1781263409522-06f1d4a6f3af?auto=format&fit=crop&w=2000&q=80', 'published', true),
  ('Women''s Enterprise Graduation 2026', 'womens-enterprise-graduation-2026', 'Celebrate 64 women completing six months of trade training in tailoring, catering and hairdressing.', '<p>Join us to celebrate the 2026 class of the Women''s Enterprise Programme. Graduates will show their work, receive starter kits and share what comes next for their businesses.</p><p>Family, friends, partners and anyone curious about the programme are welcome. Light refreshments will be served.</p>', '2026-11-02', '11:00', '14:00', 'Abeokuta Civic Centre', 'Ibara, Abeokuta, Ogun State', 'https://maps.google.com/?q=Ibara,+Abeokuta', 'https://images.unsplash.com/photo-1666281269793-da06484657e8?auto=format&fit=crop&w=2000&q=80', 'published', false),
  ('Back to School Volunteer Drive', 'back-to-school-volunteer-drive', 'Help pack 1,200 school kits with uniforms, books and stationery for the new term.', '<p>We need around 60 volunteers to pack and label school kits for pupils across our partner schools. No experience needed. We will brief everyone on arrival.</p><p>Please wear comfortable clothes. Lunch and water are provided.</p>', '2026-11-16', '10:00', '16:00', 'Mubil Foundation Warehouse', 'Ikorodu Road, Ikorodu, Lagos', 'https://maps.google.com/?q=Ikorodu,+Lagos', 'https://images.unsplash.com/photo-1560220604-1985ebfe28b1?auto=format&fit=crop&w=2000&q=80', 'published', false),
  ('Annual Fundraising Dinner', 'annual-fundraising-dinner', 'An evening with partners and supporters to share results from the year and plan the next one.', '<p>Our annual dinner brings together the people who make the work possible. Hear directly from programme graduates and see the results from the year.</p><p>Tables and individual seats are available. All proceeds go to the Back to School programme.</p>', '2026-12-04', '18:30', '22:00', 'Eko Hotel and Suites', 'Adetokunbo Ademola Street, Victoria Island, Lagos', 'https://maps.google.com/?q=Eko+Hotel,+Victoria+Island', 'https://images.unsplash.com/photo-1781263378197-9ea12f94b827?auto=format&fit=crop&w=2000&q=80', 'published', false),
  ('Water Committee Training: Iseyin', 'water-committee-training-iseyin', 'Refresher training on maintenance and record keeping for community water committees.', '<p>Members of the Iseyin water committees met for a one-day refresher on pump maintenance, simple repairs and keeping clear records of fees collected.</p>', '2026-09-16', '10:00', '15:00', 'Iseyin Town Hall', 'Iseyin, Oyo State', 'https://maps.google.com/?q=Iseyin,+Oyo', 'https://images.unsplash.com/photo-1543181077-099f32f30a1c?auto=format&fit=crop&w=2000&q=80', 'published', false),
  ('Reading Week at Ifo Primary', 'reading-week-ifo-primary', 'Five days of reading circles, storytelling and a book swap for 400 pupils.', '<p>Volunteers ran reading circles and storytelling sessions across every class, finishing with a book swap that sent each pupil home with a new book.</p>', '2026-08-20', '09:00', '13:00', 'Ifo Community Primary School', 'Ifo, Ogun State', 'https://maps.google.com/?q=Ifo,+Ogun', 'https://images.unsplash.com/photo-1744809482817-9a9d4fc280af?auto=format&fit=crop&w=2000&q=80', 'published', false),
  ('Draft: Partner Breakfast', 'draft-partner-breakfast', 'Draft event used to check that unpublished events stay hidden.', '<p>This event is a draft and must never appear on the public site.</p>', '2026-10-27', '08:00', '10:00', 'To be confirmed', 'Lagos', null, 'https://images.unsplash.com/photo-1515658323406-25d61c141a6e?auto=format&fit=crop&w=2000&q=80', 'draft', false)
insert into public.posts (status, title, slug, excerpt, category, author, cover_image_url, publish_date, body) values
  ('published', 'How 40 schools kept 9,800 children in class this year', 'how-40-schools-kept-children-in-class', 'Fees, uniforms and a mentor for every child. Here is what changed in our Back to School partner schools.', 'Education', 'Tunde Okafor', 'https://images.unsplash.com/photo-1770843093640-c44ae557928b?auto=format&fit=crop&w=2000&q=80', '2026-10-04T18:04:56.977Z', '<p>When a child is sent home for unpaid fees, the chance they return drops every week they are away. That is why Back to School starts with the fees, but it does not stop there.</p><p>This year we supported 9,800 pupils across 41 partner schools in Lagos, Ogun and Oyo. Each child received a uniform, books and stationery, and was matched with a volunteer mentor who checks in every term.</p><h2>What the numbers say</h2><p>Attendance in partner schools rose from 78% to 91% over the year. Ninety-two percent of the children we support moved up to the next class, compared with 74% before they joined the programme.</p><blockquote><p>The mentors changed everything. The children know someone outside their family is expecting them in class.</p></blockquote><p>Head teachers tell us the mentor visits matter as much as the money. A short conversation each term is often enough to spot a problem before a child drops out.</p><p>Next year we plan to add eight more schools in Ibadan North, where the waiting list is longest.</p>'),
  ('published', 'From a roadside tray to a tailoring shop', 'from-roadside-tray-to-tailoring-shop', 'Amina Bello trained with our Women''s Enterprise programme in 2023. Today she employs two apprentices.', 'Stories', 'Funmilayo Adeyemi', 'https://images.unsplash.com/photo-1693305966408-dd1b55b1e117?auto=format&fit=crop&w=2000&q=80', '2026-09-28T18:04:56.977Z', '<p>Amina used to sell groundnuts from a tray beside the Lafenwa road. On a good day she made enough for her children''s meals. On a bad day she made nothing.</p><p>In 2023 she joined the Women''s Enterprise programme and chose tailoring. For six months she trained three days a week with a mentor in Abeokuta.</p><blockquote><p>Before the training I sold from a tray by the road. Today I run a tailoring shop and two young women learn the trade from me.</p></blockquote><p>Her starter kit included a sewing machine, an overlocker and fabric for her first orders. Her savings group helped her rent a small shop front a year later.</p><p>Amina now trains two apprentices of her own, both referred by the programme.</p>'),
  ('published', 'Health days reach 14,000 people screened', 'health-days-reach-14000-screened', 'Our quarterly community health days passed a new milestone, with 1,900 people referred to partner clinics.', 'Health', 'Ngozi Eze', 'https://images.unsplash.com/photo-1781263378223-1e09658a7567?auto=format&fit=crop&w=2000&q=80', '2026-09-21T18:04:56.977Z', '<p>Since the first community health day in 2019, nurses and volunteers have screened more than 14,000 people for blood pressure, blood sugar and malaria.</p><p>Around one in seven people screened is referred for follow-up care. Our community health volunteers check in with each of them within two weeks to make sure they reached the clinic.</p><p>The next health day is in Makoko. Everyone is welcome and no appointment is needed.</p>'),
  ('published', 'Every water point still working, five years on', 'every-water-point-still-working', 'Our annual check of 18 boreholes found all of them running, thanks to the community water committees.', 'Water', 'Ibrahim Musa', 'https://images.unsplash.com/photo-1553775927-a071d5a6a39a?auto=format&fit=crop&w=2000&q=80', '2026-09-07T18:04:56.977Z', '<p>Many water projects fail within a few years because nobody is responsible for repairs. From the start, each of our water points has been run by a committee elected by the community.</p><p>This year''s inspection found all 18 boreholes working. Committees had carried out 23 small repairs using fees they collected themselves.</p>'),
  ('published', 'Our 2025 annual report is out', '2025-annual-report', 'Audited accounts and programme results for 2025, including how every naira was spent.', 'Announcements', 'Ibrahim Musa', 'https://images.unsplash.com/photo-1666281134747-caa676fc2201?auto=format&fit=crop&w=2000&q=80', '2026-08-23T18:04:56.977Z', '<p>Our 2025 annual report is now available to download from the About page. It includes audited accounts and results for each programme.</p><p>In 2025, 78% of spending went directly to programmes, 12% to training community volunteers, 5% to fundraising and 5% to administration.</p>'),
  ('published', 'Meet the volunteers behind Reading Week', 'meet-the-reading-week-volunteers', 'Forty volunteers spent a week reading with 400 pupils in Ifo. Three of them tell us why.', 'Stories', 'Tunde Okafor', 'https://images.unsplash.com/photo-1744809495173-217ca4faa8bc?auto=format&fit=crop&w=2000&q=80', '2026-08-16T18:04:56.977Z', '<p>Reading Week started as a small idea: give every pupil in one school a week of stories. This year forty volunteers joined, from university students to retired teachers.</p><p>Each volunteer ran a reading circle of ten pupils for an hour a day. On Friday every pupil took home a book of their own.</p>'),
  ('draft', 'Draft: Partner update', 'draft-partner-update', 'Draft post used to check that unpublished posts stay hidden.', 'Announcements', 'Mubil Team', 'https://images.unsplash.com/photo-1515658323406-25d61c141a6e?auto=format&fit=crop&w=2000&q=80', '2026-10-06T18:04:56.977Z', '<p>This post is a draft and must never appear on the public site.</p>')
